//! Token-text aliases llama.cpp promotes at load time.
//!
//! GENERATED by engine/scripts/gen_special_aliases.py -- do not edit by hand.
//!
//! Source: `src/llama-vocab.cpp` of the llama.cpp checkout at
//! `/home/reeds/llama.cpp`, sha256 `dab35ad158ccae5cb6064d960243ae7a6a045a09e0c4335f6491328750f8ad01`.
//!
//! llama.cpp reads `tokenizer.ggml.token_type` and then *overrides* it: any
//! token spelled like one of these is forced to CONTROL (or, for the gpt-oss
//! quartet, to USER_DEFINED). Qwen2.5-3B ships `</s>` as `token_type = 1`
//! NORMAL, and llama.cpp logs `control-looking token: 128247 '</s>' was not
//! control-type` while loading it.
//!
//! The override is invisible with `parse_special = false` -- CONTROL tokens
//! are skipped by `tokenizer_st_partition` anyway -- which is why it can go
//! unnoticed for as long as nobody tokenizes a prompt with
//! `parse_special = true`. See `build_specials` and `SpecialPromotion`.

/// One auto-detect block: the GGUF key that suppresses it, and the spellings
/// that satisfy it when the key is absent.
pub struct AliasGroup {
    /// The `tokenizer.ggml.<slot>_token_id` key whose absence lets this block run.
    pub slot: &'static str,
    /// Aliases in source order; the first match wins, as upstream.
    pub aliases: &'static [&'static str],
}

